from __future__ import annotations
from typing import FrozenSet, Sequence, TypeVar
T = TypeVar("T")
Subset = FrozenSet[T]
Topology = FrozenSet[Subset[T]]

def consensus(topologies: Sequence[Topology[T]]) -> Topology[T]:
    """Return the sets declared open by every channel."""
    if not topologies:
        raise ValueError("At least one channel is required")
    shared = set(topologies[0])
    for topology in topologies[1:]:
        shared.intersection_update(topology)
    return frozenset(shared)

def strict_collapse_witness(old: Topology[T], new: Topology[T]) -> Subset[T] | None:
    """Return an old shared open rejected by the new channel."""
    for candidate in old:
        if candidate not in new:
            return candidate
    return None
